Task: Your factory needs a new `FactoryRobot` to handle tasks. Implement the `FactoryRobot` class using composition by integrating a `GripperArm` and a `ScannerSensor`. Ensure all component methods handle edge cases with early return patterns.

Submitted code:
```
class GripperArm {
  constructor() {
    this.holdingItem = false;
  }

  grab(item) {
    // Early return if busy
    if (this.holdingItem) {
      return "Arm is already holding an item.";
    }

    this.holdingItem = true;
    return `Arm grabbed ${item}.`;
  }

  release() {
    // Early return if empty
    if (!this.holdingItem) {
      return "Arm is not holding any item to release.";
    }

    this.holdingItem = false;
    return "Arm released item.";
  }
}

class ScannerSensor {
  scanArea(range) {
    // Input validation with early return (Guard Clause)
    if (range <= 0 || range > 100) {
      return "Invalid scan range. Must be between 1 and 100.";
    }

    return `Scanned area with range ${range} units.`;
  }
}

class FactoryRobot {
  constructor(id) {
    this.id = id;
    // Composition: The robot "has a" arm and "has a" scanner
    this.arm = new GripperArm();
    this.scanner = new ScannerSensor();
  }

  performGrab(item) {
    // Delegation: The robot tells the arm to do the work
    return `Robot ${this.id}: ${this.arm.grab(item)}`;
  }

  performRelease() {
    return `Robot ${this.id}: ${this.arm.release()}`;
  }

  performScan(range) {
    return `Robot ${this.id}: ${this.scanner.scanArea(range)}`;
  }
}

// --- Usage ---
const bot = new FactoryRobot("RX-7");

console.log(bot.performScan(50));      // Robot RX-7: Scanned area with range 50 units.
console.log(bot.performGrab("Crate")); // Robot RX-7: Arm grabbed Crate.
console.log(bot.performGrab("Box"));   // Robot RX-7: Arm is already holding an item.
console.log(bot.performRelease());     // Robot RX-7: Arm released item.

```

